package br.com.serviceflow.api.dto.domain;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.List; import java.math.BigDecimal; import java.time.*;
public final class DomainDtos { private DomainDtos(){}
 public record ClienteIn(@NotBlank @Size(max=150) String name,@NotBlank @Size(max=30) String phone,@Size(max=30) String whatsapp,@Size(max=1000) String notes){} public record ClienteOut(Long id,String name,String phone,String whatsapp,String notes,LocalDateTime createdAt){}
 public record VeiculoIn(@NotNull @Positive Long clientId,@NotBlank @Size(max=80) String brand,@NotBlank @Size(max=80) String model,@Size(max=10) String plate,@Size(max=40) String color){} public record VeiculoOut(Long id,Long clientId,String brand,String model,String plate,String color){}
 public record ServicoIn(@NotBlank @Size(max=120) String name,@NotNull @PositiveOrZero @Digits(integer=10,fraction=2) BigDecimal price,@NotNull @Positive @Max(1440) Integer durationMin,Boolean active){} public record ServicoOut(Long id,String name,BigDecimal price,Integer durationMin,Boolean active){}
 public record ItemIn(@NotNull Long productId,@NotNull @Positive @Max(100000) Integer quantity){} public record ItemOut(Long productId,String name,Integer quantity,BigDecimal unitPrice){}
 public record OrdemIn(@NotNull Long clientId,Long vehicleId,Long serviceId,@Valid List<ItemIn> items,String description,@NotNull LocalDate date,@NotNull LocalTime time,@NotNull @PositiveOrZero BigDecimal price,String notes){} public record OrdemOut(Long id,String code,Long clientId,Long vehicleId,Long serviceId,String description,LocalDate date,LocalTime time,BigDecimal price,String notes,String status,String paymentMethod,Boolean paid,List<ItemOut> items){} public record StatusIn(@NotBlank String status,@Pattern(regexp="PIX|DINHEIRO|CREDITO|DEBITO", message="Forma de pagamento inválida") String paymentMethod,Boolean paid){}
 public record DespesaIn(@NotBlank @Size(max=255) String description,@NotBlank @Size(max=40) String category,@NotNull @Positive @Digits(integer=10,fraction=2) BigDecimal amount,@NotNull LocalDate date,@Size(max=1000) String notes){} public record DespesaOut(Long id,String description,String category,BigDecimal amount,LocalDate date,String notes){}
 public record FinanceiroOut(BigDecimal realized,BigDecimal forecast,BigDecimal expenses,BigDecimal profit,long finished,long canceled,BigDecimal averageTicket){}
 public record EmpresaIn(@NotBlank String name,@NotBlank String segment,@NotBlank String ownerName,@NotBlank @Email String email,@NotBlank String plan){}
 public record OnboardingServico(@NotBlank @Size(max=120) String name,@NotNull @PositiveOrZero @Digits(integer=10,fraction=2) BigDecimal price,@Positive @Max(1440) Integer durationMin){}
 public record OnboardingProduto(@NotBlank @Size(max=120) String name,@NotNull @PositiveOrZero @Digits(integer=10,fraction=2) BigDecimal price,@NotNull @PositiveOrZero @Max(1000000) Integer stock){}
 public record OnboardingIn(@NotBlank @Size(max=150) String name,@NotBlank @Size(max=80) String segment,@NotBlank @Pattern(regexp="SERVICOS|VENDAS", message="Modo deve ser SERVICOS ou VENDAS") String usageMode,@NotNull Boolean usesVehicle,@NotNull Boolean usesDuration,@Pattern(regexp="^#[0-9A-Fa-f]{6}$", message="Cor deve estar no formato #RRGGBB") String themeColor,@Valid List<OnboardingServico> services,@Valid List<OnboardingProduto> products){}
 public record ProdutoIn(@NotBlank @Size(max=120) String name,@NotNull @PositiveOrZero @Digits(integer=10,fraction=2) BigDecimal price,@NotNull @PositiveOrZero @Max(1000000) Integer stock,Boolean active){} public record ProdutoOut(Long id,String name,BigDecimal price,Integer stock,Boolean active){}
 public record EntradaIn(@NotBlank @Size(max=180) String description,@NotBlank @Size(max=40) String category,@NotNull @Positive @Digits(integer=10,fraction=2) BigDecimal amount,@NotNull LocalDate date,@Size(max=1000) String notes){} public record EntradaOut(Long id,String description,String category,BigDecimal amount,LocalDate date,String notes){}
 public record CategoriaIn(@NotBlank @Size(max=40) String name,@NotBlank @Pattern(regexp="DESPESA|ENTRADA", message="Tipo deve ser DESPESA ou ENTRADA") String type,Boolean active){} public record CategoriaOut(Long id,String name,String type,Boolean active){}
 public record TemaIn(@NotBlank @Pattern(regexp="^#[0-9A-Fa-f]{6}$", message="Cor deve estar no formato #RRGGBB") String color){}
}
